func (q *Queries) NextScheduledDose(ctx context.Context, arg NextScheduledDoseParams) (string, error) {
	row := q.db.QueryRow(ctx, nextScheduledDose,
		arg.FamilyID,
		arg.Vaccine,
		arg.SubjectMemberID,
		arg.SubjectChildID,
	)
	var dose string
	err := row.Scan(&dose)
	return dose, err
}

